      if (b.querySelector('.fd-mark') || speciesSlugFor(b.getAttribute('data-sp-name')) !== slug) return;
      var e = findSpeciesEntry(entries, b.getAttribute('data-sp-col'), b.getAttribute('data-sp-legacy'), b.getAttribute('data-sp-name'));
      if (!e) return;
