            var dd = '';
            for (i = 0; i < ring.length; i++) {
              var cp = project(ring[i][1], ring[i][0], size.width, size.height, box); // [lon, lat]
              dd += (i ? 'L' : 'M') + (cp.x + ox).toFixed(1) + ' ' + (cp.y + oy).toFixed(1);
            }
